 for t in select * from jsonb_to_recordset('[{"identity":"k2_private.guard_order_delivery_charge_v1()","before":"a7996740a83ac7881f582e23a600c43cfe6974b869668aa118d1a9bc6976a766","after":"8a3d22eb5ee128b8b491bc9e85ff33af98704eebfafdb40a70a1d797277430af","body":"\ndeclare v_snapshot k2_private.order_delivery_snapshots;v_order public.order_requests;v_acceptance k2_private.express_delivery_acceptances;\nbegin\n if tg_op=''UPDATE'' then\n  select * into v_snapshot from k2_private.order_delivery_snapshots where order_id=old.id;\n  if not found then\n   if old.channel_source=''website'' and (\n    new.id is distinct from old.id\n    or new.channel_source is distinct from old.channel_source\n    or new.shop_id is distinct from old.shop_id\n    or new.idempotency_key is distinct from old.idempotency_key\n    or new.fulfillment_method is distinct from old.fulfillment_method\n    or new.delivery_address is distinct from old.delivery_address\n    or (new.payment_status is distinct from old.payment_status and new.payment_status not in (''failed'',''refunded''))\n    or ((new.request_fingerprint is distinct from old.request_fingerprint\n     or new.subtotal is distinct from old.subtotal\n     or new.discount_amount is distinct from old.discount_amount\n     or new.total_amount is distinct from old.total_amount\n     or new.shipping_amount is distinct from old.shipping_amount\n     or new.shipping_quote_status is distinct from old.shipping_quote_status\n     or new.customer_delivery_confirmed_at is distinct from old.customer_delivery_confirmed_at) and not exists(select 1 from k2_private.order_delivery_construction_context c\n     where c.order_id=old.id and c.backend_pid=pg_catalog.pg_backend_pid()\n      and c.transaction_id=pg_catalog.pg_current_xact_id()))) then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n   end if;\n   if old.channel_source is distinct from ''website'' and new.channel_source=''website'' then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n   end if;\n   return new;\n  end if;\n  if new.id is distinct from old.id or new.channel_source is distinct from old.channel_source\n   or new.shop_id is distinct from old.shop_id then\n   raise exception using errcode=''22023'',message=''K2_ORDER_CHARGE_IMMUTABLE'';\n  end if;\n  v_order:=new;\n else\n  -- Deferred INSERT: original and persisted admission identity both matter.\n  select * into v_order from public.order_requests where id=new.id;\n  if not found then\n   if new.channel_source=''website'' then raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';end if;\n   return null;\n  end if;\n  if new.channel_source<>''website'' and v_order.channel_source<>''website'' then return null;end if;\n  select * into v_snapshot from k2_private.order_delivery_snapshots where order_id=v_order.id;\n  if not found then raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';end if;\n end if;\n select * into v_acceptance from k2_private.express_delivery_acceptances where order_id=v_order.id;\n if v_order.idempotency_key is distinct from v_snapshot.idempotency_key\n  or v_order.request_fingerprint is distinct from v_snapshot.request_fingerprint\n  or v_order.fulfillment_method is distinct from v_snapshot.fulfillment_method\n  or v_order.delivery_address is distinct from v_snapshot.delivery_address\n  or v_order.subtotal is distinct from v_snapshot.subtotal\n  or v_order.discount_amount is distinct from v_snapshot.discount_amount\n  or v_order.total_amount is distinct from coalesce(v_acceptance.total_amount,v_snapshot.total_amount)\n  or v_order.customer_delivery_confirmed_at is distinct from coalesce(v_acceptance.accepted_at,v_snapshot.accepted_at) then\n  raise exception using errcode=''22023'',message=''K2_ORDER_CHARGE_IMMUTABLE'';\n end if;\n if v_snapshot.quote->>''service''=''express'' then\n  if v_acceptance.order_id is null then\n   if v_order.shipping_amount is distinct from 0::numeric or v_order.shipping_quote_status is distinct from ''pending_quote''\n    or v_order.payment_status not in (''not_requested'',''unpaid'',''failed'') then\n    raise exception using errcode=''22023'',message=''K2_DELIVERY_ACCEPTANCE_REQUIRED'';\n   end if;\n  elsif v_order.shipping_amount is distinct from v_acceptance.fee_minor::numeric/100\n    or v_order.shipping_quote_status is distinct from ''customer_confirmed'' then\n   raise exception using errcode=''22023'',message=''K2_ORDER_CHARGE_IMMUTABLE'';\n  end if;\n else\n  if v_order.shipping_quote_status<>''customer_confirmed''\n   or v_order.shipping_amount is distinct from (v_snapshot.quote->>''feeMinor'')::numeric/100 then\n   raise exception using errcode=''22023'',message=''K2_ORDER_CHARGE_IMMUTABLE'';\n  end if;\n end if;\n if tg_op=''UPDATE'' then return new;end if;\n return null;\nend ","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"k2_private.guard_order_delivery_items_v1()","before":"6a862a754b9eeacc523d4ee03040bf241b1e963c946dd7f342b7fabd1a2d6931","after":"33cf4ee1fba6070ec064ce6c77bf5b3e9f5a7d816ba1e60284797f7c7ce01b25","body":"\nbegin\n if tg_op=''TRUNCATE'' then\n  if exists(select 1 from public.order_requests o where o.channel_source=''website''\n   and not exists(select 1 from k2_private.order_delivery_snapshots s where s.order_id=o.id)) then\n   raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n elsif (tg_op in (''UPDATE'',''DELETE'') and exists(select 1 from public.order_requests o\n  where o.id=old.order_request_id and o.channel_source=''website''\n   and not exists(select 1 from k2_private.order_delivery_snapshots s where s.order_id=o.id)))\n  or (tg_op=''UPDATE'' and exists(select 1 from public.order_requests o\n   where o.id=new.order_request_id and o.channel_source=''website''\n    and not exists(select 1 from k2_private.order_delivery_snapshots s where s.order_id=o.id))) then\n  raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n end if;\n if tg_op=''TRUNCATE'' then\n  if exists(select 1 from k2_private.order_delivery_snapshots) then raise exception using errcode=''22023'',message=''K2_ORDER_CHARGE_IMMUTABLE'';end if;\n  return null;\n end if;\n if (tg_op in (''UPDATE'',''DELETE'') and exists(select 1 from k2_private.order_delivery_snapshots where order_id=old.order_request_id))\n  or (tg_op in (''INSERT'',''UPDATE'') and exists(select 1 from k2_private.order_delivery_snapshots where order_id=new.order_request_id)) then\n  raise exception using errcode=''22023'',message=''K2_ORDER_CHARGE_IMMUTABLE'';\n end if;\n if tg_op=''DELETE'' then return old;end if;return new;\nend ","acl":["postgres=X/postgres"],"config":["search_path=\"\""],"definer":true},{"identity":"public.set_order_delivery_details(uuid, numeric, text, text, text, boolean, text)","before":"0461e0caf52742815e413a348e87968b230746bf10a46b858b8d1f2bd97bb902","after":"faf9c7e15c24ab00a037b84d50538bc355fb50a8ead855dd44f3d45ab6504e8d","body":"\ndeclare v_order public.order_requests; v_quote_status text; v_delivery_status text;\nbegin\n  if not public.is_staff() then raise exception ''Staff access required''; end if;\n  if coalesce(p_shipping_amount, -1) < 0 then raise exception ''Shipping amount cannot be negative''; end if;\n  if nullif(trim(coalesce(p_courier_name, '''')), '''') is null then raise exception ''Courier name is required''; end if;\n  if nullif(trim(coalesce(p_note, '''')), '''') is null then raise exception ''A delivery communication note is required''; end if;\n  select * into v_order from public.order_requests where id = p_order_request_id for update;\n  if not found then raise exception ''Order request not found''; end if;\n  if v_order.status in (''fulfilled'', ''cancelled'') then raise exception ''Delivery details are closed for this order''; end if;\n\n  if v_order.channel_source in (''shopee'', ''tiktok'', ''lazada'') then\n    v_quote_status := ''platform_charged'';\n    v_delivery_status := case when v_order.status = ''confirmed'' then ''ready_to_pack'' else v_order.delivery_status end;\n  elsif coalesce(p_customer_confirmed, false) then\n    v_quote_status := ''customer_confirmed'';\n    v_delivery_status := case when v_order.status = ''confirmed'' then ''ready_to_pack'' else ''awaiting_quote'' end;\n  else\n    v_quote_status := ''quoted'';\n    v_delivery_status := ''awaiting_customer'';\n  end if;\n\n  if v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id) then\n    v_quote_status:=v_order.shipping_quote_status;v_delivery_status:=v_order.delivery_status;\n  end if;\n  update public.order_requests set\n    shipping_amount = p_shipping_amount,\n    total_amount = case when v_order.channel_source=''website'' and not exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id)\n      then v_order.total_amount else subtotal - discount_amount + p_shipping_amount end,\n    shipping_quote_status = v_quote_status,\n    courier_name = trim(p_courier_name),\n    tracking_number = nullif(trim(p_tracking_number), ''''),\n    waybill_url = nullif(trim(p_waybill_url), ''''),\n    customer_delivery_confirmed_at = case when v_order.channel_source=''website'' or exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id)\n      then v_order.customer_delivery_confirmed_at else case when v_quote_status in (''platform_charged'', ''customer_confirmed'') then now() else null end end,\n    delivery_status = case when exists(select 1 from k2_private.order_delivery_snapshots where order_id=v_order.id)\n      then v_order.delivery_status else v_delivery_status end,\n    updated_at = now()\n  where id = v_order.id returning * into v_order;\n  insert into public.order_request_events (order_request_id, from_status, to_status, reason, actor_id, metadata)\n  values (v_order.id, v_order.status, v_order.status, trim(p_note), auth.uid(), jsonb_build_object(\n    ''event'', ''delivery_details_updated'', ''shipping_amount'', p_shipping_amount,\n    ''courier_name'', trim(p_courier_name), ''shipping_quote_status'', v_quote_status,\n    ''tracking_number'', v_order.tracking_number, ''waybill_url'', v_order.waybill_url\n  ));\n  return v_order;\nend;\n","acl":null,"config":["search_path=public"],"definer":true}]'::jsonb)
