  for t in select * from jsonb_to_recordset('[{"identity":"k2_private.guard_legacy_website_item_insert_v1()","body":"begin\n if exists(select 1 from public.order_requests o where o.id=new.order_request_id\n  and o.channel_source=''website'' and not exists(\n   select 1 from k2_private.order_delivery_snapshots s where s.order_id=o.id)) then\n  raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n end if;\n return null;\nend;"},{"identity":"k2_private.guard_order_delivery_construction_v1()","body":"begin\n if new.channel_source<>''website'' then return null;end if;\n if tg_name=''order_delivery_construction_start'' then\n  insert into k2_private.order_delivery_construction_context(order_id,backend_pid,transaction_id)\n  values(new.id,pg_catalog.pg_backend_pid(),pg_catalog.pg_current_xact_id());\n elsif tg_name=''order_delivery_construction_end'' then\n  if not exists(select 1 from k2_private.order_delivery_snapshots where order_id=new.id) then\n   raise exception using errcode=''22023'',message=''K2_DELIVERY_REVIEW_REQUIRED'';\n  end if;\n  delete from k2_private.order_delivery_construction_context where order_id=new.id\n   and backend_pid=pg_catalog.pg_backend_pid() and transaction_id=pg_catalog.pg_current_xact_id();\n  if not found then raise exception using errcode=''55000'',message=''K2_DELIVERY_CONSTRUCTION_CONTEXT_REQUIRED'';end if;\n else raise exception using errcode=''55000'',message=''K2_DELIVERY_CONSTRUCTION_TRIGGER_INVALID'';end if;\n return null;\nend;"}]'::jsonb) as x(identity text,body text) loop
