   or b.provolatile<>'v' or b.prokind<>'f' or b.prolang<>(select oid from pg_language where lanname='plpgsql')
   or b.proacl::text[] is distinct from array['postgres=X/postgres'] then raise exception 'K2_LEGACY_REVIEW_INSERT_AUTHORITY_DRIFT';end if;
